function validate([nums, n]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value in nums is a whole number from 1 to 10^4.';
  for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  if (!Number.isInteger(n) || n < 1 || n > 2147483647) return 'n is a whole number from 1 to 2^31 - 1.';
  return null;
}

