function minPatches(nums, n) {
  if (n > 24) {
    // Large n: patch each gap before using the next value, then patch until n is covered.
    let covered = 0, count = 0;
    for (const value of nums) {
      while (covered < n && value > covered + 1) { covered = 2 * covered + 1; count++; }
      if (covered >= n) return count;
      covered += value;
    }
    while (covered < n) { covered = 2 * covered + 1; count++; }
    return count;
  }
  // Small n: buildable[s] says whether sum s can be formed; try 0, 1, 2, ... patches from 1..n.
  const extend = (buildable, value) => {
    const next = buildable.slice();
    for (let s = 0; s + value <= n; s++) if (buildable[s]) next[s + value] = true;
    return next;
  };
  let base = Array(n + 1).fill(false);
  base[0] = true;
  for (const value of nums) base = extend(base, value);
  const search = (buildable, left, low) => {
    if (buildable.every(Boolean)) return true;
    if (left === 0) return false;
    for (let value = low; value <= n; value++) if (search(extend(buildable, value), left - 1, value)) return true;
    return false;
  };
  for (let k = 0; ; k++) if (search(base, k, 1)) return k;
}

